        m_aHandler->endDocument();
}
void XFSaxStream::StartElement(const OUString& oustr)
{
    if (m_aHandler.is())
        m_aHandler->startElement(oustr, m_pAttrList->GetAttributeList());
    m_pAttrList->Clear();
}
void XFSaxStream::EndElement(const OUString& oustr)
{
